1096	
1097	static void sccb_sda_low(void)     { gpio_drive_low(g_cam_sda_pin); }
1098	static void sccb_sda_release(void) { gpio_release(g_cam_sda_pin); }
1099	static void sccb_scl_low(void)     { gpio_drive_low(g_cam_scl_pin); }
1100	static void sccb_scl_release(void) { gpio_release(g_cam_scl_pin); }
1101	static bool sccb_sda_read(void)    { return gpio_read_input(g_cam_sda_pin); }
1102	
1103	static int sccb_scl_wait_high(void)
1104	{
1105	  int timeout = SCCB_TIMEOUT_ITER;
1106	  while (timeout-- > 0)
1107	    {
1108	      if (gpio_read_input(g_cam_scl_pin)) return 0;
1109	      up_udelay(SCCB_HALF_PERIOD_US);
1110	    }
1111	  syslog(LOG_ERR, "[camera] SCL stuck low\n");
1112	  return -ETIMEDOUT;
1113	}
1114	
1115	static int sccb_start(void)
1116	{
1117	  int ret;
1118	
1119	  sccb_sda_release();
1120	  sccb_scl_release();
1121	  up_udelay(SCCB_HALF_PERIOD_US);
1122	
1123	  /* Bus-free check */
1124	
1125	  if (!gpio_read_input(g_cam_scl_pin))
1126	    {
1127	      ret = sccb_scl_wait_high();
1128	      if (ret < 0) return ret;
1129	    }
1130	
1131	  if (!gpio_read_input(g_cam_sda_pin))
1132	    {
1133	      /* SDA stuck low — 9-clock recovery */
1134	
1135	      int i;
1136	      for (i = 0; i < 9; i++)
1137	        {
1138	          sccb_scl_low();
1139	          up_udelay(SCCB_HALF_PERIOD_US);
1140	          sccb_scl_release();
1141	          ret = sccb_scl_wait_high();
1142	          if (ret < 0) return ret;
1143	          up_udelay(SCCB_HALF_PERIOD_US);
1144	          if (gpio_read_input(g_cam_sda_pin)) break;
1145	        }
1146	      if (!gpio_read_input(g_cam_sda_pin))
1147	        {
1148	          syslog(LOG_ERR, "[camera] SDA stuck low — recovery failed\n");
1149	          return -EIO;
1150	        }
1151	    }
1152	
1153	  /* START: SDA falls while SCL high */
1154	
1155	  sccb_sda_low();
1156	  up_udelay(SCCB_HALF_PERIOD_US);
1157	  sccb_scl_low();
1158	  up_udelay(SCCB_HALF_PERIOD_US);
1159	
1160	  return 0;
1161	}
1162	
1163	static int sccb_stop(void)
1164	{
1165	  int ret;
1166	
1167	  sccb_sda_low();
1168	  up_udelay(SCCB_HALF_PERIOD_US);
1169	
1170	  sccb_scl_release();
1171	  ret = sccb_scl_wait_high();
1172	  if (ret < 0) return ret;
1173	
1174	  up_udelay(SCCB_HALF_PERIOD_US);
1175	
1176	  sccb_sda_release();
1177	  up_udelay(SCCB_HALF_PERIOD_US);
1178	
1179	  return 0;

1290	
1291	  return value;
1292	
1293	stop_fail:
1294	  stop_ret = sccb_stop();
1295	  return (stop_ret < 0) ? stop_ret : ret;
1296	}
