1330	/****************************************************************************
1331	 * MCLK
1332	 *
1333	 * mclk_enable_24mhz modifies 4 registers:
1334	 *   1. GPIO FUNC (shared P24-P31) — only P27 bits
1335	 *   2. P27 GPIO CFG — set second_func=1 (bit6)
1336	 *   3. CLK DIV — cksel + ckdiv
1337	 *   4. CLK EN — enable gate
1338	 *
1339	 * Restore uses read-modify-write on shared registers.
1340	 ****************************************************************************/
1341	
1342	static void mclk_save_state(mclk_state_t *ms)
1343	{
1344	  uint32_t val;
1345	
1346	  /* Save only the MCLK-relevant bit fields from shared registers */
1347	
1348	  val = getreg32(CAMERA_CLK_DIV_REG);
1349	  ms->clk_div = val & ((CAMERA_CKSEL_MASK << CAMERA_CKSEL_POS) |
1350	                        (CAMERA_CKDIV_MASK << CAMERA_CKDIV_POS));
1351	
1352	  val = getreg32(CAMERA_CLK_EN_REG);
1353	  ms->clk_en = val & CAMERA_CIS_AUXS_CKEN_BIT;
1354	
1355	  val = getreg32(CAMERA_GPIO_FUNC_REG);
1356	  ms->func2431 = val & (CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
1357	
1358	  ms->p27_cfg = getreg32(BK7258_GPIO_CFG(CAMERA_MCLK_REQUIRED_PIN));
1359	  ms->valid   = true;
1360	}
1361	
1362	static void mclk_restore_state(const mclk_state_t *ms)
1363	{
1364	  uint32_t val;
1365	
1366	  if (!ms->valid) return;
1367	
1368	  /* 1. Gate OFF first — avoid glitch while source/divider changes */
1369	
1370	  val = getreg32(CAMERA_CLK_EN_REG);
1371	  val &= ~CAMERA_CIS_AUXS_CKEN_BIT;
1372	  putreg32(val, CAMERA_CLK_EN_REG);
1373	
1374	  /* 2. Restore cksel/ckdiv — read-modify-write, safe while gate off */
1375	
1376	  val = getreg32(CAMERA_CLK_DIV_REG);
1377	  val &= ~((CAMERA_CKSEL_MASK << CAMERA_CKSEL_POS) |
1378	            (CAMERA_CKDIV_MASK << CAMERA_CKDIV_POS));
1379	  val |= ms->clk_div;
1380	  putreg32(val, CAMERA_CLK_DIV_REG);
1381	
1382	  /* 3. Restore P27 function select — read-modify-write FUNC reg */
1383	
1384	  val = getreg32(CAMERA_GPIO_FUNC_REG);
1385	  val &= ~(CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
1386	  val |= ms->func2431;
1387	  putreg32(val, CAMERA_GPIO_FUNC_REG);
1388	
1389	  /* 4. Restore P27 GPIO CFG (direction/latch/pull) — per-pin, safe */

1590	  for (i = 0; i < count; i++)
1591	    {
1592	      ret = sccb_write_reg(table[i][0], table[i][1]);
1593	      if (ret < 0)
1594	        {
1595	          syslog(LOG_ERR,
1596	                 "[camera] table[%d] reg 0x%02X NACK (err=%d)\n",
1597	                 i, table[i][0], ret);
1598	          return ret;
1599	        }
1600	    }
1601	
1602	  return 0;
1603	}
