1648	/****************************************************************************
1649	 * DVP Module Clock and Interrupt Enable
1650	 *
1651	 * From ARMino yuv_buf_driver.c:yuv_buf_init_common():
1652	 *   1. Enable YUV_BUF power (PM voting — skipped, assume always on)
1653	 *   2. Enable H264 clock (bit[0] of CLK_EN_REG) — needed for bus
1654	 *   3. Enable YUV_BUF clock (bit[3] of CLK_EN_REG)
1655	 *   4. Enable system interrupt (bit[26] of INT_32_63_EN_REG)
1656	 *   5. Init global control (soft reset + clock gate bypass)
1657	 *
1658	 * All register writes use field-level RMW on shared registers.
1659	 ****************************************************************************/
1660	
1661	typedef struct
1662	{
1663	  uint32_t clk_en;       /* CLK_EN_REG bits we modify */
1664	  uint32_t int_en;       /* INT_32_63_EN_REG bits we modify */
1665	  uint32_t global_ctrl;  /* YUV_BUF REG_0x02 value */
1666	  bool     valid;
1667	} dvp_module_state_t;
1668	
1669	static dvp_module_state_t g_dvp_module_saved = { .valid = false };
1670	static bool g_dvp_module_enabled = false;
1671	
1672	static int dvp_module_clk_enable(void)
1673	{
1674	  uint32_t val;
1675	
1676	  if (g_dvp_module_enabled)
1677	    {
1678	      return 0;
1679	    }
1680	
1681	  /* Save register values for restore — only bits we modify */
1682	
1683	  val = getreg32(CAMERA_CLK_EN_REG);
1684	  g_dvp_module_saved.clk_en = val & (CAMERA_H264_CLKEN_BIT |
1685	                                      CAMERA_YUV_BUF_CLKEN_BIT);
1686	
1687	  val = getreg32(CAMERA_SYS_INT_32_63_REG);
1688	  g_dvp_module_saved.int_en = val & CAMERA_YUVB_INT_EN_BIT;
1689

1690	  g_dvp_module_saved.global_ctrl = getreg32(YUV_BUF_REG_0x02);
1691	  g_dvp_module_saved.valid = true;
1692	
1693	  /* Step 1: Enable H264 clock — needed for YUV_BUF internal bus
1694	   * From ARMino sys_drv_set_h264_clk_en(1)
1695	   */
1696	
1697	  val = getreg32(CAMERA_CLK_EN_REG);
1698	  val |= CAMERA_H264_CLKEN_BIT;
1699	  putreg32(val, CAMERA_CLK_EN_REG);
1700	
1701	  /* Step 2: Enable YUV_BUF clock
1702	   * From ARMino sys_drv_set_yuv_buf_clk_en(1)
1703	   */
1704	
1705	  val = getreg32(CAMERA_CLK_EN_REG);
1706	  val |= CAMERA_YUV_BUF_CLKEN_BIT;
1707	  putreg32(val, CAMERA_CLK_EN_REG);
1708	
1709	  /* Step 3: Enable system interrupt for YUV_BUF
1710	   * From ARMino sys_drv_int_group2_enable(YUV_BUF_INTERRUPT_CTRL_BIT)
1711	   * YUV_BUF_INTERRUPT_CTRL_BIT = (1 << 26)
1712	   */
1713	
1714	  val = getreg32(CAMERA_SYS_INT_32_63_REG);
1715	  val |= CAMERA_YUVB_INT_EN_BIT;
1716	  putreg32(val, CAMERA_SYS_INT_32_63_REG);
1717	
1718	  /* Step 4: Init global control — soft reset + clock gate bypass
1719	   * From ARMino yuv_buf_ll_init():
1720	   *   hw->global_ctrl.soft_reset = 0;    // assert reset
1721	   *   hw->global_ctrl.soft_reset = 1;    // deassert reset
1722	   *   hw->global_ctrl.clk_gate_bypass = 1; // bypass clock gate
1723	   */
1724	
1725	  val = getreg32(YUV_BUF_REG_0x02);
1726	  val &= ~YUV_BUF_GLOBAL_SOFT_RESET;  /* assert reset */
1727	  putreg32(val, YUV_BUF_REG_0x02);
1728	
1729	  val |= YUV_BUF_GLOBAL_SOFT_RESET;   /* deassert reset */
1730	  val |= YUV_BUF_GLOBAL_CLK_GATE;     /* bypass clock gate */
1731	  putreg32(val, YUV_BUF_REG_0x02);
1732	
1733	  g_dvp_module_enabled = true;
1734	
1735	  syslog(LOG_INFO,
1736	         "[camera] DVP module clock enabled: CLK_EN=0x%08lX INT_EN=0x%08lX\n",
1737	         (unsigned long)getreg32(CAMERA_CLK_EN_REG),
1738	         (unsigned long)getreg32(CAMERA_SYS_INT_32_63_REG));
1739	
1740	  return 0;
1741	}
1742	
1743	static void dvp_module_clk_disable(void)
1744	{
1745	  uint32_t val;
1746	
1747	  if (!g_dvp_module_enabled) return;
1748	
1749	  /* Assert soft reset first */
1750	
1751	  val = getreg32(YUV_BUF_REG_0x02);
1752	  val &= ~YUV_BUF_GLOBAL_SOFT_RESET;
1753	  putreg32(val, YUV_BUF_REG_0x02);
1754	
1755	  /* Disable system interrupt for YUV_BUF */
1756	
1757	  val = getreg32(CAMERA_SYS_INT_32_63_REG);
1758	  val &= ~CAMERA_YUVB_INT_EN_BIT;
1759	  val |= g_dvp_module_saved.int_en;  /* restore saved bits */
1760	  putreg32(val, CAMERA_SYS_INT_32_63_REG);
1761	
1762	  /* Disable YUV_BUF clock */
1763	
1764	  val = getreg32(CAMERA_CLK_EN_REG);
1765	  val &= ~CAMERA_YUV_BUF_CLKEN_BIT;
1766	  val |= (g_dvp_module_saved.clk_en & CAMERA_YUV_BUF_CLKEN_BIT);
1767	  putreg32(val, CAMERA_CLK_EN_REG);
1768	
1769	  /* Disable H264 clock */
1770	
1771	  val = getreg32(CAMERA_CLK_EN_REG);
1772	  val &= ~CAMERA_H264_CLKEN_BIT;
1773	  val |= (g_dvp_module_saved.clk_en & CAMERA_H264_CLKEN_BIT);
1774	  putreg32(val, CAMERA_CLK_EN_REG);
1775	
1776	  /* Restore global control register */
1777	
1778	  putreg32(g_dvp_module_saved.global_ctrl, YUV_BUF_REG_0x02);
1779	
1780	  g_dvp_module_enabled = false;
1781	
1782	  syslog(LOG_INFO, "[camera] DVP module clock disabled\n");
1783	}
