1785	/****************************************************************************
1786	 * DVP Controller Configuration (CIS / YUV_BUF)
1787	 *
1788	 * The YUV_BUF controller at 0x48020000 captures DVP data and writes it
1789	 * to external memory via its internal DMA.  Configuration steps:
1790	 *   1. Save all register values for restore
1791	 *   2. Set resolution (x_pixel = width/8, y_pixel = height/8)
1792	 *   3. Set format (YUV mode, YUYV)
1793	 *   4. Set polarity (HSYNC/VSYNC/PCLK from Kconfig)
1794	 *   5. Set frame buffer base address
1795	 *   6. Start YUV mode (set yuv_mode bit in CTRL)
1796	 *
1797	 * All register writes use field-level RMW on shared registers.
1798	 ****************************************************************************/
1799	
1800	static void dvp_ctrl_save_state(dvp_ctrl_state_t *s)
1801	{
1802	  s->ctrl       = getreg32(YUV_BUF_REG_0x04);
1803	  s->pixel      = getreg32(YUV_BUF_REG_0x05);
1804	  s->em_base    = getreg32(YUV_BUF_REG_0x08);
1805	  s->int_en     = getreg32(YUV_BUF_REG_0x09);
1806	  s->int_status = getreg32(YUV_BUF_REG_0x0a);
1807	  s->valid      = true;
1808	}
1809	
1810	static void dvp_ctrl_restore_state(const dvp_ctrl_state_t *s)
1811	{
1812	  if (!s->valid) return;
1813	
1814	  /* Disable interrupts first */
1815	
1816	  putreg32(0, YUV_BUF_REG_0x09);
1817	
1818	  /* Clear any pending interrupt status */
1819	
1820	  putreg32(YUV_BUF_INT_STATUS_MASK, YUV_BUF_REG_0x0a);
1821	
1822	  /* Restore registers in order: CTRL, PIXEL, EM_BASE, INT_EN */
1823	
1824	  putreg32(s->ctrl, YUV_BUF_REG_0x04);
1825	  putreg32(s->pixel, YUV_BUF_REG_0x05);
1826	  putreg32(s->em_base, YUV_BUF_REG_0x08);
1827	  putreg32(s->int_en, YUV_BUF_REG_0x09);
1828	}
