2049	 * Name: dvp_irq_handler
2050	 *
2051	 * Description:
2052	 *   ISR for DVP (YUV_BUF) controller interrupts.
2053	 *   Handles VSYNC falling edge (frame start) and YUV arrived (frame done).
2054	 *
2055	 ****************************************************************************/
2056	
2057	static int dvp_irq_handler(int irq, void *context, void *arg)
2058	{
