2060	
2061	  /* Read interrupt status */
2062	
2063	  status = getreg32(YUV_BUF_REG_0x0a);
2064	
2065	  /* VSYNC falling edge — frame start */
2066	
2067	  if (status & YUV_BUF_INT_VSYNC_NEGE)
2068	    {
2069	      g_dvp_vsync_count++;
2070	    }
2071	
2072	  /* YUV arrived — frame data written to memory */
2073	
2074	  if (status & YUV_BUF_INT_YUV_ARV)
2075	    {
2076	      g_dvp_frame_count++;
2077	
2078	      /* Ping-pong: if streaming, advance to next buffer */
2079	
2080	      if (g_stream_active)
2081	        {
2082	          int next_buf = 1 - g_cur_buf;
2083	
2084	          if (g_ready_buf < 0 && next_buf != g_busy_buf)
2085	            {
2086	              g_ready_buf = g_cur_buf;
2087	              g_cur_buf = next_buf;
2088	              g_pingpong_count++;
2089	              putreg32((uint32_t)(uintptr_t)g_camera_buf[g_cur_buf],
2090	                       YUV_BUF_REG_0x08);
2091	            }
2092	          else
2093	            {
2094	              g_drop_count++;
2095	            }
2096	        }
2097	    }
2098	
2099	  /* Clear all pending interrupts by writing 1s */
2100	
2101	  putreg32(status & YUV_BUF_INT_STATUS_MASK, YUV_BUF_REG_0x0a);
2102	
2103	  return OK;
2104	}
