2736	 * Name: bk7258_camera_stop
2737	 *   Turn off MCLK, power off, deconfig DVP pins, free frame buffers.
2738	 ****************************************************************************/
2739	
2740	int bk7258_camera_stop(void)
2741	{
2742	  uint32_t val;
2743	
2744	  /* Detach DVP IRQ first — stop interrupts before modifying registers */
2745	
2746	  dvp_irq_detach();
2747	
2748	  /* Restore DVP controller registers and disable module clock */
2749	
2750	  dvp_ctrl_deconfig();
2751	
2752	  /* Also disable module clock in case dvp_ctrl_config was never called
2753	   * but dvp_module_clk_enable was called directly.
2754	   */
2755	
2756	  dvp_module_clk_disable();
2757	
2758	  /* Turn off MCLK gate */
2759	
2760	  val = getreg32(CAMERA_CLK_EN_REG);
2761	  val &= ~CAMERA_CIS_AUXS_CKEN_BIT;
2762	  putreg32(val, CAMERA_CLK_EN_REG);
2763	
2764	  /* Power off — drive PWR pin inactive */
2765	
2766	  if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED)
2767	    {
2768	#ifdef CONFIG_CAMERA_PWR_ACTIVE_HIGH
2769	      gpio_drive_low(g_cam_pwr_pin);
2770	#else
2771	      gpio_set_output_high(g_cam_pwr_pin);
2772	#endif
2773	    }
2774	
2775	  /* Deconfig DVP pins */
2776	
2777	  dvp_io_deconfig();
2778	
2779	  /* Free frame buffers */
2780	
2781	  camera_framebuf_free();
2782	
2783	  syslog(LOG_INFO, "[camera] Stopped — MCLK off, power off, pins restored\n");
2784	  return 0;
2785	}
