2805	    {
2806	      buf[i] = (uint8_t)(i & 0xFF);
2807	    }
2808	
2809	  /* Readback verify:
2810	   *   - First 256 bytes: full check
2811	   *   - Last 256 bytes: full check
2812	   *   - Every 1024 bytes: sampled check
2813	   */
2814	
2815	  for (i = 0; i < CAMERA_FRAME_SIZE; i++)
2816	    {
2817	      bool check = false;
2818	
2819	      if (i < 256)                              check = true;
2820	      else if (i >= CAMERA_FRAME_SIZE - 256)    check = true;
2821	      else if ((i & 1023) == 0)                 check = true;
2822	
2823	      if (check && buf[i] != (uint8_t)(i & 0xFF))
2824	        {
2825	          syslog(LOG_ERR,
2826	                 "[camera] Framebuf[%d] mismatch: 0x%02X vs 0x%02X\n",
2827	                 i, buf[i], (uint8_t)(i & 0xFF));
