2829	        }
2830	    }
2831	
2832	  syslog(LOG_INFO,
2833	         "[camera] Framebuf verify OK (%d bytes, buf0=0x%08lX)\n",
2834	         CAMERA_FRAME_SIZE, (unsigned long)g_camera_buf[0]);
2835	
2836	  return 0;
2837	}
