2850	/****************************************************************************
2851	 * Name: bk7258_camera_sync
2852	 *
2853	 * Description:
2854	 *   Phase 1 Round 2 Step 4a: DVP controller config + interrupt counting.
2855	 *
2856	 *   Configures the CIS controller (YUV_BUF) for 640x480 YUV capture,
2857	 *   attaches VSYNC/YUV_ARRIVED interrupt handlers, and waits for a
2858	 *   configurable number of VSYNC edges (default 10) to verify the
2859	 *   camera is producing valid sync signals.
2860	 *
2861	 *   Prerequisites: camera init must have been run (MCLK on, GC2145
2862	 *   configured for output).  Frame buffers must be allocated.
2863	 *
2864	 *   On exit: interrupts are detached, controller registers restored.
2865	 *
2866	 ****************************************************************************/
2867	
2868	int bk7258_camera_sync(void)
2869	{
2870	  int ret;
2871	  int timeout_ms;
2872	  uint32_t vsync_target;
2873	  uint32_t vsync_prev;
2874	  uint32_t vsync_now;
2875	
2876	  /* Check DVP pins are configured (camera init must have been run) */
2877	
2878	  if (!g_dvp_pins_configed)
2879	    {
2880	      syslog(LOG_ERR,
2881	             "[camera] DVP pins not configured — run 'camera init' first\n");
2882	      return -ENODEV;
2883	    }
2884	
2885	  /* Check frame buffers allocated */
2886	
2887	  if (!g_framebuf_allocated)
2888	    {
2889	      syslog(LOG_ERR,
2890	             "[camera] Frame buffers not allocated — run 'camera buf' first\n");
2891	      return -ENOMEM;
2892	    }
2893	
2894	  /* Configure DVP controller — use buf[0] as output target.
2895	   * The controller needs a valid em_base_addr even for sync-only test.
2896	   */
2897	
2898	  ret = dvp_ctrl_config((uint32_t)(uintptr_t)g_camera_buf[0]);
2899	  if (ret < 0)
2900	    {
2901	      syslog(LOG_ERR, "[camera] DVP ctrl config failed: %d\n", ret);
2902	      goto cleanup_ctrl;
2903	    }
2904	
2905	  /* Attach interrupt handler and enable interrupts */
2906	
2907	  ret = dvp_irq_attach();
2908	  if (ret < 0)
2909	    {
2910	      syslog(LOG_ERR, "[camera] DVP IRQ attach failed: %d\n", ret);
2911	      goto cleanup_irq;
2912	    }
2913	
2914	  /* Wait for VSYNC edges — timeout 5 seconds */
2915	
2916	  vsync_target = 10;
2917	  timeout_ms   = 5000;
2918	  vsync_prev   = g_dvp_vsync_count;
2919	
2920	  syslog(LOG_INFO,
2921	         "[camera] Waiting for %lu VSYNC edges (timeout %d ms)...\n",
2922	         (unsigned long)vsync_target, timeout_ms);
2923	
2924	  while (timeout_ms > 0)
2925	    {
2926	      vsync_now = g_dvp_vsync_count;
2927	      if (vsync_now >= vsync_target)
2928	        {
2929	          break;
2930	        }
2931	
2932	      /* Print progress every 100 VSYNC edges */
2933	
2934	      if (vsync_now != vsync_prev && (vsync_now % 100) == 0)

2960	             (unsigned long)vsync_now, (unsigned long)vsync_target);
2961	      syslog(LOG_ERR,
2962	             "[camera] Check: MCLK on P27, sensor powered, "
2963	             "DVP pins P29-P39\n");
2964	      ret = -ETIMEDOUT;
2965	    }
2966	  else
2967	    {
2968	      syslog(LOG_INFO, "[camera] DVP sync OK — %lu VSYNC edges captured\n",
2969	             (unsigned long)vsync_now);
2970	      ret = 0;
