2986	/****************************************************************************
2987	 * Name: bk7258_camera_grab
2988	 *
2989	 * Description:
2990	 *   Phase 1 Round 2 Step 4b: DMA single frame capture to PSRAM.
2991	 *
2992	 *   Configures the CIS controller, attaches interrupts, fills the
2993	 *   target buffer with 0x5A pattern, waits for one complete frame
2994	 *   (YUV_ARRIVED interrupt), then hexdumps the first 256 bytes.
2995	 *
2996	 *   Prerequisites: camera init + camera buf must have been run.
2997	 *
2998	 *   On exit: interrupts are detached, controller registers restored.
2999	 *
3000	 ****************************************************************************/
3001	
3002	int bk7258_camera_grab(void)
3003	{
3004	  int ret;
3005	  int timeout_ms;
3006	  uint32_t frame_start;
3007	  volatile uint8_t *buf;
3008	  int i;
3009	
3010	  /* Check DVP pins are configured */
3011	
3012	  if (!g_dvp_pins_configed)
3013	    {
3014	      syslog(LOG_ERR,
3015	             "[camera] DVP pins not configured — run 'camera init' first\n");
3016	      return -ENODEV;
3017	    }
3018	
3019	  /* Check frame buffers allocated */
3020	
3021	  if (!g_framebuf_allocated)
3022	    {
3023	      syslog(LOG_ERR,
3024	             "[camera] Frame buffers not allocated — run 'camera buf' first\n");
3025	      return -ENOMEM;
3026	    }
3027	
3028	  /* Fill target buffer with 0x5A pattern — allows detection of
3029	   * whether DMA actually wrote data.
3030	   */
3031	
3032	  buf = g_camera_buf[0];
3033	  syslog(LOG_INFO, "[camera] Filling buf[0] with 0x5A pattern (%d bytes)\n",
3034	         CAMERA_FRAME_SIZE);
3035	
3036	  for (i = 0; i < CAMERA_FRAME_SIZE; i++)
3037	    {
3038	      buf[i] = 0x5A;
3039	    }
3040	
3041	  /* Configure DVP controller — output to buf[0] */
3042	
3043	  ret = dvp_ctrl_config((uint32_t)(uintptr_t)g_camera_buf[0]);
3044	  if (ret < 0)
3045	    {
3046	      syslog(LOG_ERR, "[camera] DVP ctrl config failed: %d\n", ret);
3047	      goto cleanup_ctrl;
3048	    }
3049	
3050	  /* Attach interrupt handler */
3051	
3052	  ret = dvp_irq_attach();
3053	  if (ret < 0)
3054	    {
3055	      syslog(LOG_ERR, "[camera] DVP IRQ attach failed: %d\n", ret);
3056	      goto cleanup_irq;
3057	    }
3058	
3059	  /* Wait for one complete frame — YUV_ARRIVED interrupt.
3060	   * Timeout 5 seconds.
3061	   */
3062	
3063	  frame_start = g_dvp_frame_count;
3064	  timeout_ms  = 5000;
3065	
3066	  syslog(LOG_INFO, "[camera] Waiting for frame (timeout %d ms)...\n",
3067	         timeout_ms);
3068	
3069	  while (timeout_ms > 0)
3070	    {
3071	      if (g_dvp_frame_count > frame_start)
3072	        {
3073	          break;
3074	        }
3075	
3076	      up_udelay(1000);  /* 1 ms */
3077	      timeout_ms--;
3078	    }
3079	
3080	  if (g_dvp_frame_count <= frame_start)
3081	    {
3082	      syslog(LOG_ERR,
3083	             "[camera] TIMEOUT: no frame received in 5s "
3084	             "(VSYNC=%lu FRAME=%lu)\n",
3085	             (unsigned long)g_dvp_vsync_count,
3086	             (unsigned long)g_dvp_frame_count);
3087	      ret = -ETIMEDOUT;
3088	      goto cleanup_irq;
3089	    }
3090	
3091	  syslog(LOG_INFO, "[camera] Frame captured — VSYNC=%lu FRAME=%lu\n",
3092	         (unsigned long)g_dvp_vsync_count,
3093	         (unsigned long)g_dvp_frame_count);
3094	
3095	  /* Hexdump first 256 bytes of captured frame */
3096	
3097	  syslog(LOG_INFO, "[camera] First 256 bytes of captured frame:\n");
3098	
3099	  for (i = 0; i < 256; i += 16)
3100	    {
3101	      syslog(LOG_INFO,
3102	             "  %04X: %02X %02X %02X %02X %02X %02X %02X %02X "
3103	             "%02X %02X %02X %02X %02X %02X %02X %02X\n",
3104	             i,
3105	             buf[i + 0],  buf[i + 1],  buf[i + 2],  buf[i + 3],
3106	             buf[i + 4],  buf[i + 5],  buf[i + 6],  buf[i + 7],
3107	             buf[i + 8],  buf[i + 9],  buf[i + 10], buf[i + 11],
3108	             buf[i + 12], buf[i + 13], buf[i + 14], buf[i + 15]);
3109	    }
3110	
3111	  /* Check if buffer still contains 0x5A pattern — if so, DMA didn't write */
3112	
3113	  {
3114	    bool all_5a = true;
3115	    for (i = 0; i < 256; i++)
3116	      {
3117	        if (buf[i] != 0x5A)
3118	          {
3119	            all_5a = false;
3120	            break;
3121	          }
3122	      }
3123	
3124	    if (all_5a)
3125	      {
3126	        syslog(LOG_ERR,
3127	               "[camera] WARNING: buf[0] still 0x5A — DMA may not have "
3128	               "written data\n");
3129	        ret = -EIO;
3130	      }
3131	    else
3132	      {
3133	        syslog(LOG_INFO,
3134	               "[camera] DMA write verified — buf[0] contains non-0x5A data\n");
3135	        ret = 0;
3136	      }
3137	  }
3138	
3139	cleanup_irq:
3140	  dvp_irq_detach();
3141	
3142	cleanup_ctrl:
3143	  dvp_ctrl_deconfig();
3144	
3145	  return ret;
3146	}
