3155	
3156	int bk7258_camera_stream(int n_frames)
3157	{
3158	  int ret;
3159	  uint32_t elapsed_ms;

3156	int bk7258_camera_stream(int n_frames)
3157	{
3158	  int ret;
3159	  uint32_t elapsed_ms;
3160	  int captured;
3161	  int timeout_ms;
3162	  int i;
3163	
3164	  if (n_frames <= 0) n_frames = 30;
3165	  else if (n_frames > STREAM_BUF_MAX) n_frames = STREAM_BUF_MAX;
3166	
3167	  if (!g_dvp_pins_configed)
3168	    {
3169	      syslog(LOG_ERR, "[camera] DVP pins not configured\n");
3170	      return -ENODEV;
3171	    }
3172	
3173	  if (!g_framebuf_allocated)
3174	    {
3175	      syslog(LOG_ERR, "[camera] Frame buffers not allocated\n");
3176	      return -ENOMEM;
3177	    }
3178	
3179	  ret = dvp_ctrl_config((uint32_t)(uintptr_t)g_camera_buf[0]);
3180	  if (ret < 0) goto cleanup_ctrl;
3181	
3182	  ret = dvp_irq_attach();
