3192	  g_stream_active   = true;
3193	
3194	  syslog(LOG_INFO,
3195	         "[camera] Stream start: capturing %d frames "
3196	         "(buf[0]=0x%08lX buf[1]=0x%08lX)\n",
3197	         n_frames,
3198	         (unsigned long)(uintptr_t)g_camera_buf[0],
3199	         (unsigned long)(uintptr_t)g_camera_buf[1]);
3200	
3201	  captured = 0;
3202	
3203	  while (captured < n_frames)
3204	    {
3205	      uint32_t frame_addr;
3206	
3207	      timeout_ms = 5000;
3208	      while (timeout_ms > 0)
3209	        {
3210	          frame_addr = dvp_frame_get();
3211	          if (frame_addr != 0) break;
3212	          up_udelay(1000);
3213	          timeout_ms--;
3214	        }
3215	
3216	      if (frame_addr == 0)
3217	        {
3218	          syslog(LOG_ERR, "[camera] TIMEOUT waiting for frame %d/%d\n",
3219	                 captured + 1, n_frames);
3220	          ret = -ETIMEDOUT;
3221	          break;
3222	        }
3223	
3224	      captured++;
3225	
3226	      {
3227	        const uint8_t *buf = (const uint8_t *)(uintptr_t)frame_addr;
3228	        uint32_t y_sum = 0;
3229	        int samples = 0;
3230	
3231	        for (i = 0; i < CAMERA_FRAME_SIZE; i += 16 * CAMERA_HRES)
3232	          {
3233	            int j;
3234	            for (j = 0; j < CAMERA_HRES; j += 16)
3235	              {
3236	                y_sum += buf[i + j];
3237	                samples++;
3238	              }
3239	          }
3240	
3241	        if (captured == 1 || captured == n_frames || (captured % 10) == 0)
3242	          {
3243	            syslog(LOG_INFO,
3244	                   "[camera] %d/%d  VSYNC=%lu  FRAME=%lu  "
3245	                   "Y_avg=%lu  drop=%lu\n",
3246	                   captured, n_frames,
3247	                   (unsigned long)g_dvp_vsync_count,
3248	                   (unsigned long)g_dvp_frame_count,
3249	                   (unsigned long)(samples > 0 ? y_sum / samples : 0),
3250	                   (unsigned long)g_drop_count);
3251	          }
3252	      }
3253	
3254	      dvp_frame_put();
3255	    }
3256	
3257	  g_stream_active = false;
3258	
3259	  elapsed_ms = g_dvp_frame_count > 0 ? (uint32_t)g_dvp_frame_count * 33 : 0;
3260	
3261	  syslog(LOG_INFO,
3262	         "[camera] Stream done: captured=%d  total=%lu  drop=%lu  vsync=%lu\n",
3263	         captured,
3264	         (unsigned long)g_pingpong_count,
3265	         (unsigned long)g_drop_count,
3266	         (unsigned long)g_dvp_vsync_count);
3267	
3268	  if (elapsed_ms > 0)
3269	    {
3270	      syslog(LOG_INFO, "[camera] Elapsed: ~%lu ms  Avg FPS: ~%lu\n",
3271	             (unsigned long)elapsed_ms,
3272	             (unsigned long)(captured * 1000 / (elapsed_ms > 0 ? elapsed_ms : 1)));
3273	    }
3274	
3275	  ret = captured > 0 ? 0 : -EIO;
3276	
3277	cleanup_irq:
3278	  dvp_irq_detach();
3279	cleanup_ctrl:
3280	  dvp_ctrl_deconfig();
3281	  return ret;
3282	}
