3284	/****************************************************************************
3285	 * YUYV → RGB565 scaled conversion
3286	 ****************************************************************************/
3287	
3288	static void yuyv_to_rgb565_scaled(const uint8_t *src,
3289	                                  uint8_t *dst,
3290	                                  int src_w, int src_h,
3291	                                  int dst_w, int dst_h)
3292	{
3293	  int sx, sy, dx, dy;
3294	  uint16_t *out = (uint16_t *)dst;
3295	  int scale_x = src_w / dst_w;
3296	  int scale_y = src_h / dst_h;
3297	
3298	  for (dy = 0; dy < dst_h; dy++)
3299	    {
3300	      sy = dy * scale_y;
3301	      const uint8_t *row = src + sy * src_w * 2;
3302	
3303	      for (dx = 0; dx < dst_w; dx++)
3304	        {
3305	          uint8_t y0;
3306	          int cb_i, cr_i, r, g, b;
3307	          uint16_t rgb;
3308	
3309	          sx = dx * scale_x;
3310	
3311	          int pair = sx / 2;
3312	          const uint8_t *p = row + pair * 4;
3313	
3314	          y0   = (sx & 1) ? p[2] : p[0];
3315	          cb_i = (int)p[1] - 128;
3316	          cr_i = (int)p[3] - 128;
3317	
3318	          r = (int)y0 + cr_i + (cr_i * 51 / 128);
3319	          g = (int)y0 - (cb_i * 28 / 81) - (cr_i * 365 / 512);
3320	          b = (int)y0 + cb_i + (cb_i * 99 / 128);
3321	
3322	          if (r < 0) r = 0;
3323	          if (r > 255) r = 255;
3324	          if (g < 0) g = 0;
3325	          if (g > 255) g = 255;
3326	          if (b < 0) b = 0;
3327	          if (b > 255) b = 255;
3328	
3329	          rgb = (uint16_t)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
3330	          out[dy * dst_w + dx] = rgb;
3331	        }
3332	    }
3333	}
