474	  int row;
475	  int row_bytes = (int)w * 2;
476	
477	  /* CASET */
478	
479	  ca[0] = (x0 >> 8) & 0xff;
480	  ca[1] = x0 & 0xff;
481	  ca[2] = (x1 >> 8) & 0xff;
482	  ca[3] = x1 & 0xff;
483	  lcd_send_cmd_data(0x2a, ca, 4);
484	
485	  /* RASET */
486	
487	  ra[0] = (y0 >> 8) & 0xff;
488	  ra[1] = y0 & 0xff;
489	  ra[2] = (y1 >> 8) & 0xff;
490	  ra[3] = y1 & 0xff;
491	  lcd_send_cmd_data(0x2b, ra, 4);
492	
493	  /* RAMWR + pixel data, one row at a time */
494	
495	  lcd_send_cmd(0x2c);
496	
497	  for (row = 0; row < (int)h; row++)
498	    {
499	      gpio_write_fast(&g_cache_dc, 1);
500	      gpio_write_fast(&g_cache_cs, 0);
501	
502	      const uint8_t *rowp = rgb565 + row * row_bytes;

