402	/****************************************************************************
403	 * Name: lcd_fill_rect
404	 *
405	 * Description:
406	 *   Fill a rectangle (x0,y0)-(x1,y1) with a single RGB565 color.
407	 *   Much smaller than full-screen fill — avoids millions of bit-bangs.
408	 *
409	 ****************************************************************************/
410	
411	static void lcd_fill_rect(uint16_t x0, uint16_t y0,
412	                          uint16_t x1, uint16_t y1,
413	                          uint16_t color)
414	{
415	  uint8_t ca[4];
416	  uint8_t ra[4];
417	  uint8_t hi = (color >> 8) & 0xff;
418	  uint8_t lo = color & 0xff;
419	  int npix = (int)(x1 - x0 + 1) * (int)(y1 - y0 + 1);
420	  int i;
421	
422	  /* CASET */
423	
424	  ca[0] = (x0 >> 8) & 0xff;
425	  ca[1] = x0 & 0xff;
426	  ca[2] = (x1 >> 8) & 0xff;
427	  ca[3] = x1 & 0xff;
428	  lcd_send_cmd_data(0x2a, ca, 4);
429	
430	  /* RASET */
431	
432	  ra[0] = (y0 >> 8) & 0xff;
433	  ra[1] = y0 & 0xff;
434	  ra[2] = (y1 >> 8) & 0xff;

436	  lcd_send_cmd_data(0x2b, ra, 4);
437	
438	  /* RAMWR + pixel data */
439	
440	  lcd_send_cmd(0x2c);
441	  gpio_write_fast(&g_cache_dc, 1);
442	  gpio_write_fast(&g_cache_cs, 0);
443	  for (i = 0; i < npix; i++)
444	    {
445	      spi_write_byte(hi);
446	      spi_write_byte(lo);
447	    }
448	
449	  gpio_write_fast(&g_cache_cs, 1);
450	}
