/****************************************************************************
 * YUYV → RGB565 scaled conversion
 ****************************************************************************/

static void yuyv_to_rgb565_scaled(const uint8_t *src,
                                  uint8_t *dst,
                                  int src_w, int src_h,
                                  int dst_w, int dst_h)
{
  int sx, sy, dx, dy;
  uint8_t *out = dst;
  int scale_x = src_w / dst_w;
  int scale_y = src_h / dst_h;

  for (dy = 0; dy < dst_h; dy++)
    {
      sy = dy * scale_y;
      const uint8_t *row = src + sy * src_w * 2;

      for (dx = 0; dx < dst_w; dx++)
        {
          uint8_t y0;
          int cb_i, cr_i, r, g, b;
          uint16_t rgb;
          int pos;

          sx = dx * scale_x;

          /* YUYV byte layout: [Y0 U Y1 V] per 2-pixel pair.
           * Source byte offset = sx * 2 (2 bytes per pixel).
           *   even pixel (sx&1==0): Y at offset 0, U at +1, V at +3
           *   odd  pixel (sx&1==1): Y at offset 2, U at -1, V at +1
           * Offset always falls on a Y byte, never on U or V.
           */

          int byte_off = sx * 2;
          const uint8_t *p = row + byte_off;

          y0   = p[0];
          cb_i = (int)((sx & 1) ? p[-1] : p[1]) - 128;
          cr_i = (int)((sx & 1) ? p[1]  : p[3]) - 128;

          r = (int)y0 + cr_i + (cr_i * 51 / 128);
          g = (int)y0 - (cb_i * 28 / 81) - (cr_i * 365 / 512);
          b = (int)y0 + cb_i + (cb_i * 99 / 128);

          if (r < 0) r = 0;
          if (r > 255) r = 255;
          if (g < 0) g = 0;
          if (g > 255) g = 255;
          if (b < 0) b = 0;
